   if(Items.Count==0){Icons.Draw(g,"search",new Rectangle(Math.Max(0,Width/2-16),45,32,32),Ui.Muted);Ui.Text(g,"Produto não encontrado",new Rectangle(0,94,Width-20,25),12,Ui.Ink,FontStyle.Bold,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);Ui.Text(g,"Tente outro nome, código ou categoria.",new Rectangle(0,125,Width-20,30),8.5f,Ui.Muted,FontStyle.Regular,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);return;}
   for(int i=0;i<Items.Count;i++){int x=(i%cols)*(w+gap),y=(i/cols)*237+ScrollOffset.Y;var r=new Rectangle(x,y,w,223);hits.Add(new KeyValuePair<Rectangle,Product>(r,Items[i]));if(y+223<0||y>Height)continue;var p=Items[i];Ui.Box(g,r,Ui.Card,SelectedProduct==p&&Focused?Ui.Green:Ui.Line,12);var art=new Rectangle(x+7,y+7,w-14,110);Color tint=Art(p.icon),ink=ArtInk(p.icon);Ui.Box(g,art,tint,Color.Empty,8);using(var b=new SolidBrush(Ui.Dark?Color.FromArgb(15,220,220,180):Color.FromArgb(80,255,255,255)))g.FillEllipse(b,x+w/2-39,y+24,78,78);Icons.Draw(g,p.icon,new Rectangle(x+w/2-25,y+36,50,50),ink);
    if(p.stock<=p.minStock)using(var b=new SolidBrush(Color.FromArgb(193,147,66)))g.FillEllipse(b,x+w-23,y+16,7,7);
    var line=Draft==null?null:Draft.cart.Find(l=>l.productId==p.id);if(line!=null){string q=D.Qty(line.quantity,p.unit);int qw=TextRenderer.MeasureText(q,Font).Width+24;Ui.Box(g,new Rectangle(x+w-qw-12,y+85,qw,23),Ui.Accent,Color.Empty,6);Ui.Text(g,q,new Rectangle(x+w-qw-10,y+85,qw-4,23),7.5f,Color.White,FontStyle.Bold,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
    Ui.Text(g,p.category,new Rectangle(x+13,y+127,w-26,17),7.5f,Ui.Muted);Ui.Text(g,p.name,new Rectangle(x+13,y+146,w-22,27),10,Ui.Ink,FontStyle.Bold);Ui.Text(g,D.Money(p.price)+" / "+p.unit,new Rectangle(x+13,y+177,w-50,22),9.5f,Ui.Green,FontStyle.Bold);Ui.Box(g,new Rectangle(x+w-36,y+176,24,24),Ui.Soft,Color.Empty,12);Icons.Draw(g,"plus",new Rectangle(x+w-30,y+182,12,12),Ui.Green);Ui.Text(g,p.stock>0?D.Qty(p.stock,p.unit)+" "+p.unit+" em estoque":"Sem estoque",new Rectangle(x+13,y+202,w-26,15),7.5f,Ui.Muted);
   }
  }
  protected override void OnMouseClick(MouseEventArgs e){base.OnMouseClick(e);Focus();var h=hits.FirstOrDefault(x=>x.Key.Contains(e.Location));if(h.Value==null)return;SelectedProduct=h.Value;Invalidate();if(h.Value.stock>0&&Chosen!=null)Chosen(h.Value);}
  protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);int i=Items.IndexOf(SelectedProduct);if(e.KeyCode==Keys.Enter&&SelectedProduct!=null&&Chosen!=null){Chosen(SelectedProduct);e.Handled=true;return;}int n=e.KeyCode==Keys.Right?i+1:e.KeyCode==Keys.Left?i-1:e.KeyCode==Keys.Down?i+Columns():e.KeyCode==Keys.Up?i-Columns():i;if(n!=i&&Items.Count>0){SelectedProduct=Items[Math.Max(0,Math.Min(n,Items.Count-1))];ScrollOffset=new Point(0,Math.Max(0,(Items.IndexOf(SelectedProduct)/Columns())*237-Height/2));Invalidate();e.Handled=true;}}
  public static Color Art(string icon){if(Ui.Dark)return icon=="cake"?Color.FromArgb(65,44,38):icon=="coffee"||icon=="juice"?Color.FromArgb(42,57,39):Color.FromArgb(64,55,37);return icon=="cake"?Color.FromArgb(247,233,228):icon=="coffee"?Color.FromArgb(237,240,230):icon=="juice"?Color.FromArgb(234,240,232):Color.FromArgb(247,240,226);}
  public static Color ArtInk(string icon){return icon=="cake"?Color.FromArgb(197,139,120):icon=="coffee"||icon=="juice"?Color.FromArgb(139,163,117):Color.FromArgb(173,137,75);}
  public void ThemeChanged(){BackColor=Ui.Bg;Invalidate();}
 }
